import{_ as i,o as a,c as e,ai as n}from"./chunks/framework.BxxKhjs3.js";const t="/pub-blog/assets/image-20250925155609382.psg1bjDn.png",l="/pub-blog/assets/image-20250925155902652.D3lD92fw.png",r="/pub-blog/assets/image-20250925160014444.B0fiHY5i.png",h="/pub-blog/assets/image-20250822223258675.CJHnmYEl.png",p="/pub-blog/assets/wanshaoweixin.DWzIcicW.jpg",u=JSON.parse('{"title":"十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价/十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价.md","filePath":"鸿蒙开发技巧/十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价/十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价.md","lastUpdated":1759102800000,"__rawMarkdown":"# 十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价\\n\\n## 前言\\n\\nHarmonyOS 6的beta版本来到了 beta5，也是给我们带来了不少的有趣的新特性。\\n\\n![image-20250925155609382](assets/image-20250925155609382.png)\\n\\n## 应用评论服务\\n\\n这里要介绍是beta 2 推出的 **应用评论服务**功能，用户无需进入应用市场应用详情页，可直接在应用内进行评论。\\n\\n> 指南：https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/appgallery-comment\\n>\\n> API：https://developer.huawei.com/consumer/cn/doc/harmonyos-references/appgallery-commentmanager\\n\\n![image-20250925155902652](assets/image-20250925155902652.png)\\n\\n## 接入步骤\\n\\n\\n\\n![image-20250925160014444](assets/image-20250925160014444.png)\\n\\n1. 用户需要在应用内评论应用。\\n2. 应用调用showCommentDialog接口拉起应用评论弹窗。\\n3. AppGalleryKit返回接口调用结果给应用。\\n4. 应用返回评论窗口给用户。\\n\\n## 开发步骤\\n\\n1. 导入commentManager模块及相关公共模块。\\n\\n   \\n\\n   ```typescript\\n   import { commentManager} from \'@kit.AppGalleryKit\';\\n   import { hilog } from \'@kit.PerformanceAnalysisKit\';\\n   import { BusinessError } from \'@kit.BasicServicesKit\';\\n   import type { common } from \'@kit.AbilityKit\';\\n   ```\\n\\n   \\n\\n2. 调用[showCommentDialog](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/appgallery-commentmanager)方法拉起评论弹窗。\\n\\n   \\n\\n   ```typescript\\n   try {\\n     const uiContext = this.getUIContext().getHostContext() as common.UIAbilityContext;\\n     commentManager.showCommentDialog(uiContext).then(()=>{\\n       hilog.info(0, \'TAG\', \\"succeeded in showing commentDialog.\\");\\n     }).catch((error: BusinessError<Object>) => {\\n       hilog.error(0, \'TAG\', `showCommentDialog failed, Code: ${error.code}, message: ${error.message}`);\\n     });\\n   } catch (error) {\\n     hilog.error(0, \'TAG\', `showCommentDialog failed, Code: ${error.code}, message: ${error.message}`);\\n   }\\n   ```\\n\\n3. 注意事项\\n\\n   1. 需要使用真机\\n   2. 真机需要登录华为账号\\n   3. 一年内评论过的不能再次评论\\n\\n4. 常见错误\\n\\n   | 错误码ID   | 错误信息                                                     |\\n   | :--------- | :----------------------------------------------------------- |\\n   | 1021500001 | Internal system error.                                       |\\n   | 1021500002 | Service request failed.                                      |\\n   | 1021500003 | Failed to connect to AppGallery.                             |\\n   | 1021500004 | Failed to write parameters.                                  |\\n   | 1021500005 | The app context is invalid.                                  |\\n   | 1021500006 | The user has not signed in to their HUAWEI ID.               |\\n   | 1021500007 | The user has already commented on the current version.       |\\n   | 1021500008 | The number of comments has reached the maximum limit.        |\\n   | 1021500009 | The user has already left a comment, and less than a year has elapsed since then. |\\n\\n## 总结\\n\\n​\\t这样就可以在你的项目中接入应用评论服务了。\\n\\n\\n\\n## 以往文章\\n\\n- 我的iMaHarmonyOS 知识库接入 鸿蒙6 API20 新特性了 \\n\\n  > https://mp.weixin.qq.com/s/YsbFQyi5PsndpRUaA9h_dA?token=830743671&lang=zh_CN\\n\\n- 鸿蒙创新赛 HarmonyOS 6.0.0(20) 关键特性汇总\\n\\n  > https://mp.weixin.qq.com/s/ERmgSAIT8B8njFqtyPx9IQ\\n\\n- 可可图片编辑 HarmonyOS（4）图片裁剪-canvas\\n\\n  > https://mp.weixin.qq.com/s/2M3f_LNnt0YRo0qEnCnqpA\\n\\n- 可可图片编辑 HarmonyOS（3）应用间分享图片\\n\\n  > https://mp.weixin.qq.com/s/n8kkdougB4lqDHjYC7co8g\\n\\n\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n> https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248\\n\\n![](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![](assets/wanshaoweixin.jpg)"}'),o={name:"鸿蒙开发技巧/十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价/十行代码 带你极速接入鸿蒙6新特性 - 应用内打分评价.md"};function k(d,s,c,m,g,E){return a(),e("div",null,[...s[0]||(s[0]=[n("",24)])])}const F=i(o,[["render",k]]);export{u as __pageData,F as default};
